import React, { useState, useEffect } from "react";
import Sidebar from "../compornents/Sidebar";
import { database } from "../firebaseConfig";
import {
  collection,
  addDoc,
  getDocs,
  deleteDoc,
  doc,
} from "firebase/firestore";

export default function ManageTechnicians() {
  const [technicians, setTechnicians] = useState([]);
  const [formData, setFormData] = useState({ name: "", email: "", password: "" });
  const [loading, setLoading] = useState(false);

  const techCollectionRef = collection(database, "technicians");

  //  Fetch technicians
  const fetchTechnicians = async () => {
    const data = await getDocs(techCollectionRef);
    setTechnicians(data.docs.map((doc) => ({ ...doc.data(), id: doc.id })));
  };

  useEffect(() => {
    fetchTechnicians();
  }, []);

  // Add new technician
  const handleAddTechnician = async (e) => {
    e.preventDefault();
    if (!formData.name || !formData.email || !formData.password) {
      alert("Please fill all fields!");
      return;
    }
    setLoading(true);
    try {
      await addDoc(techCollectionRef, {
        name: formData.name,
        email: formData.email,
        role: "Technician",
      });
      alert("Technician added successfully!");
      setFormData({ name: "", email: "", password: "" });
      fetchTechnicians();
    } catch (error) {
      console.error("Error adding technician:", error);
    } finally {
      setLoading(false);
    }
  };

  // 🗑️ Delete technician
  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to delete this technician?")) return;
    await deleteDoc(doc(db, "technicians", id));
    fetchTechnicians();
  };

  return (
    <div className="flex h-screen bg-black text-white font-display">
      <Sidebar />

      <main className="flex-1 p-8 overflow-y-auto bg-gray-900">
        <div className="max-w-4xl mx-auto">
          {/* Header */}
          <header className="mb-8">
            <h1 className="text-4xl font-black tracking-tight">Manage Technicians</h1>
          </header>

          {/* Add Form */}
          <section className="bg-gray-800 p-6 rounded-lg shadow-md mb-8">
            <h2 className="text-2xl font-bold mb-6">Add New Technician</h2>
            <form onSubmit={handleAddTechnician} className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-base font-medium pb-2">Technician Name</label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  className="form-input w-full rounded-lg border-gray-600 bg-gray-700 text-white focus:ring-primary h-12 px-4"
                  placeholder="Enter full name"
                />
              </div>
              <div>
                <label className="block text-base font-medium pb-2">Email</label>
                <input
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  className="form-input w-full rounded-lg border-gray-600 bg-gray-700 text-white focus:ring-primary h-12 px-4"
                  placeholder="Enter email address"
                />
              </div>
              <div>
                <label className="block text-base font-medium pb-2">Password</label>
                <input
                  type="password"
                  value={formData.password}
                  onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                  className="form-input w-full rounded-lg border-gray-600 bg-gray-700 text-white focus:ring-primary h-12 px-4"
                  placeholder="Enter password"
                />
              </div>
              <div className="md:col-span-2 flex justify-end">
                <button
                  type="submit"
                  className="bg-green-600 hover:bg-green-500 text-white font-bold py-3 px-6 rounded-lg transition"
                  disabled={loading}
                >
                  {loading ? "Adding..." : "Add Technician"}
                </button>
              </div>
            </form>
          </section>

          {/* List */}
          <section className="bg-gray-800 p-6 rounded-lg shadow-md">
            <h2 className="text-2xl font-bold mb-4">Existing Technicians</h2>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="border-b border-gray-700">
                    <th className="p-4 text-sm font-semibold text-gray-400 uppercase">Name</th>
                    <th className="p-4 text-sm font-semibold text-gray-400 uppercase">Email</th>
                    <th className="p-4 text-sm font-semibold text-gray-400 uppercase">Role</th>
                    <th className="p-4 text-sm font-semibold text-gray-400 uppercase text-right">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {technicians.map((tech) => (
                    <tr key={tech.id} className="border-b border-gray-700 hover:bg-gray-700/50">
                      <td className="p-4">{tech.name}</td>
                      <td className="p-4 text-gray-400">{tech.email}</td>
                      <td className="p-4 text-gray-400">{tech.role}</td>
                      <td className="p-4 text-right">
                        <button
                          onClick={() => handleDelete(tech.id)}
                          className="text-red-500 hover:text-red-400 p-2"
                        >
                          <span className="material-symbols-outlined">delete</span>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        </div>
      </main>
    </div>
  );
}
